class InvoiceController extends Controller
{
 public function index(Request $r,CourierNotificationService $n){$n->markRead('payment_upload');$invoices=$this->filteredTenantInvoices($r)->with(['customer.user','creator','updater','issuer','canceller','voider','latestApprovedPayment.receiver','latestApprovedPayment.method'])->latest()->paginate($this->perPage($r,15))->withQueryString();$counts=['all'=>$this->tenantInvoices()->count(),'paid'=>$this->tenantInvoices()->where('payment_status','paid')->count(),'unpaid'=>$this->tenantInvoices()->whereIn('payment_status',['unpaid','partial'])->count()];$paymentMethods=$this->paymentMethods();$bulkPreviewGroups=$this->bulkInvoicePreviewGroups();return view('courier.invoices.index',compact('invoices','counts','paymentMethods','bulkPreviewGroups'));}
 public function export(Request $r):StreamedResponse{$invoices=$this->filteredTenantInvoices($r)->with('customer.user')->latest()->get();return response()->streamDownload(function()use($invoices){$o=fopen('php://output','w');fputcsv($o,['invoice_number','customer','mailbox','invoice_status','payment_status','total_jmd','due_date','created_at']);foreach($invoices as $i)fputcsv($o,[$i->invoice_number,optional(optional($i->customer)->user)->full_name,$i->mailbox,$i->invoice_status,$i->payment_status,$i->total_jmd,optional($i->due_date)->format('Y-m-d'),optional($i->created_at)->format('Y-m-d H:i:s')]);fclose($o);},'invoices-'.now()->format('Ymd-His').'.csv',['Content-Type'=>'text/csv']);}
 public function printList(Request $r){$invoices=$this->filteredTenantInvoices($r)->with('customer.user')->latest()->get();return view('courier.invoices.print',compact('invoices'));}
 public function create(Request $r){$customers=$this->tenantCustomers()->with('user')->orderBy('mailbox')->get();$pricingTiers=$this->pricingTiers();$outlets=$this->outlets();$shippingModes=$this->shippingModes();$selectedPackageIds=[];$selectedCustomerId=null;$preselectedPackage=null;if($r->filled('package_id')){$preselectedPackage=$this->directInvoiceablePackage()->with('customer.user')->findOrFail($r->integer('package_id'));abort_if(!$preselectedPackage->customer_id,422,'This package must be assigned to a customer before creating an invoice.');$selectedPackageIds=[$preselectedPackage->id];$selectedCustomerId=$preselectedPackage->customer_id;}$packages=$this->invoiceablePackages($selectedPackageIds)->with(['customer.user','customer.pricingTier','outlet'])->orderBy('mailbox')->latest()->get();if($preselectedPackage&&!$packages->contains('id',$preselectedPackage->id)){$packages->push($preselectedPackage->loadMissing(['customer.user','customer.pricingTier','outlet']));}$this->refreshPackageFees($packages);return view('courier.invoices.create',compact('customers','packages','pricingTiers','outlets','shippingModes','selectedPackageIds','selectedCustomerId','preselectedPackage'));}
 public function store(Request $r,CustomerNotificationService $n){$this->validateInvoiceRequest($r,true);$selected=$this->selectedInvoicePackagesForCustomers($r->input('package_ids',[]));if(!$r->filled('customer_id')&&$selected->isEmpty())throw ValidationException::withMessages(['package_ids'=>'Select at least one manifested package to invoice.']);$groups=$selected->groupBy('customer_id');if(!$r->filled('customer_id')||$groups->count()>1){$created=DB::transaction(fn()=> $groups->map(fn($pkgs)=>$this->createInvoiceForCustomerFromRequest($pkgs->first()->customer,$pkgs->values(),$r))->filter()->values());return $this->afterInvoicesCreated($created,$n,'Created '.$created->count().' invoice(s).');}$customer=$this->tenantCustomers()->findOrFail($r->customer_id);$invoice=DB::transaction(fn()=> $this->createInvoiceForCustomerFromRequest($customer,$this->selectedInvoicePackages($r->input('package_ids',[]),$customer->id),$r,$r->invoice_number?:null));return $this->afterInvoicesCreated(collect([$invoice]),$n,'Invoice created successfully.');}
 public function show($id,CourierNotificationService $n){$invoice=$this->tenantInvoices()->with(['tenant','outlet','customer.user','items.package.manifest','payments.method','payments.receiver','payments.approver','creator','updater','issuer','canceller','voider','latestApprovedPayment.receiver','latestApprovedPayment.method'])->findOrFail($id);if($invoice->verified_at&&$invoice->items->contains(fn($item)=>$item->package&&(!$item->package->date_delivered||!$this->isFinalHandoverStatus($item->package)))){$this->markInvoicePackagesDelivered(collect([$invoice->id]));$invoice=$this->tenantInvoices()->with(['tenant','outlet','customer.user','items.package.manifest','payments.method','payments.receiver','payments.approver','creator','updater','issuer','canceller','voider','latestApprovedPayment.receiver','latestApprovedPayment.method'])->findOrFail($id);}$n->markRead('payment_upload',['invoice_id'=>$invoice->id]);$paymentMethods=$this->paymentMethods();return view('courier.invoices.show',compact('invoice','paymentMethods'));}
 public function edit($id){$invoice=$this->tenantInvoices()->findOrFail($id);$this->ensureInvoiceIsNotLocked($invoice);$customers=$this->tenantCustomers()->with('user')->orderBy('mailbox')->get();$pricingTiers=$this->pricingTiers();$outlets=$this->outlets();$shippingModes=$this->shippingModes();$currentPackageIds=$invoice->items()->whereNotNull('package_id')->pluck('package_id')->all();$packages=$this->invoiceablePackages($currentPackageIds)->with(['customer.user','customer.pricingTier','outlet'])->orderBy('mailbox')->latest()->get();$this->refreshPackageFees($packages);$invoice->load('items');$selectedPricingTierId=optional($invoice->customer)->pricing_tier_id;return view('courier.invoices.edit',compact('invoice','customers','packages','pricingTiers','outlets','shippingModes','selectedPricingTierId'));}
 public function update(Request $r,$id){$invoice=$this->tenantInvoices()->with('items')->findOrFail($id);$this->ensureInvoiceIsNotLocked($invoice);$this->validateInvoiceRequest($r,false,$invoice->id);$customer=$this->tenantCustomers()->findOrFail($r->customer_id);DB::transaction(function()use($r,$invoice,$customer){$existingPackageIds=$invoice->items->whereNotNull('package_id')->pluck('package_id')->all();$originalPackageIds=collect($r->input('original_package_ids',[]))->map(fn($id)=>(int)$id)->filter()->unique()->values()->all();$selectedPackageIds=collect($r->input('package_ids',[]))->merge($r->input('selected_package_ids',[]))->map(fn($id)=>(int)$id)->filter()->merge($originalPackageIds)->merge($existingPackageIds)->unique()->values()->all();if(empty($selectedPackageIds)&&!empty($existingPackageIds))$selectedPackageIds=$existingPackageIds;$pkgs=$this->selectedInvoicePackages($selectedPackageIds,$customer->id,array_merge($existingPackageIds,$originalPackageIds));if(!empty($selectedPackageIds)&&$pkgs->count()!==count($selectedPackageIds))throw ValidationException::withMessages(['package_ids'=>'One or more selected packages could not be matched to this invoice customer. Refresh the page and try again.']);$this->refreshPackageFees($pkgs,$invoice);$this->applyExistingInvoiceItemCharges($pkgs,$invoice,$r->input('package_charges',[]));$tot=$this->forceInvoiceDiscountFromRequest($r,$this->invoiceTotals($r,$pkgs));$this->preventAccidentalInvoiceZeroOut($invoice,$pkgs,$tot,$r);$invoice->update($this->invoicePayload($customer,$tot,$r)+['invoice_number'=>$r->invoice_number,'updated_by'=>auth()->id(),'issued_by'=>$r->invoice_status==='issued'?($invoice->issued_by?:auth()->id()):$invoice->issued_by,'cancelled_by'=>$r->invoice_status==='cancelled'?auth()->id():null]);$this->persistInvoiceDiscount($invoice,$tot,$r);$this->syncInvoiceItems($invoice,$pkgs);$this->markPackagesReadyForHandoff($pkgs);});return redirect()->route('courier.invoices.show',$invoice)->with('success','Invoice updated successfully.');}
 public function destroy($id){return $this->voidInvoice($id);} public function download($id){return InvoicePdf::download($this->tenantInvoices()->with(['tenant','outlet','customer.user','items.package','payments'])->findOrFail($id));}
 public function bulkStore(Request $r,CustomerNotificationService $n){return $this->bulkInvoiceRedirect($this->createBulkInvoices($this->bulkInvoiceablePackages(),$this->bulkInvoiceData($r),$n),'courier.invoices.index');}
 public function bulkCreateForManifest(Manifest $manifest){$this->authorizeManifestForInvoices($manifest);$manifest->load(['items.package.customer.user','items.package.invoiceItems']);$bulkPreviewGroups=$this->bulkInvoicePreviewGroups($manifest);return view('courier.invoices.bulk-manifest',compact('manifest','bulkPreviewGroups'));}
 public function bulkStoreForManifest(Request $r,Manifest $manifest,CustomerNotificationService $n){$this->authorizeManifestForInvoices($manifest);return $this->bulkInvoiceRedirect($this->createBulkInvoices($this->bulkInvoiceablePackages($manifest),$this->bulkInvoiceData($r),$n),'courier.manifests.show',[$manifest]);}
 public function sendSelected(Request $r,CustomerNotificationService $n){$d=$r->validate(['invoice_ids'=>'required|array|min:1','invoice_ids.*'=>'integer']);$sent=0;$invoices=$this->tenantInvoices()->whereIn('id',$d['invoice_ids'])->with(['tenant','customer.user','items.package'])->get();foreach($invoices as $i)if(!$i->isLocked()&&$n->invoiceCreated($i)){$i->update(['email_sent'=>true]);$sent++;}return $sent?back()->with('success','Sent '.$sent.' selected invoice notification(s).'):back()->withErrors(['invoice_ids'=>'No selected invoices could be sent.']);}
 public function pay(Request $r,$id){$i=$this->tenantInvoices()->with(['items.package','payments','customer'])->findOrFail($id);$this->ensureInvoiceIsNotLocked($i);$d=$r->validate(['payment_method_id'=>'required|integer','reference_number'=>'nullable|string|max:120','amount_received'=>'nullable|numeric|min:0','notes'=>'nullable|string|max:1000','receipt'=>'nullable|file|mimes:pdf,jpg,jpeg,png,webp|max:5120','require_handoff_verification'=>'nullable|boolean','tracking_numbers'=>'nullable|string','credit_change_to_wallet'=>'nullable|boolean']);if(!$this->validPaymentMethod((int)$d['payment_method_id']))throw ValidationException::withMessages(['payment_method_id'=>'Select a valid payment method.']);$trackingNumbers=trim((string)$r->tracking_numbers);$handoverCompleted=!$r->boolean('require_handoff_verification')||$trackingNumbers!=='';$scanned=collect();if($r->boolean('require_handoff_verification')&&$trackingNumbers!=='')$scanned=$this->assertTrackingNumbersMatch($i,$trackingNumbers);$amt=$this->invoiceRemainingBalance($i);$recv=max((float)($d['amount_received']??$amt),$amt);DB::transaction(function()use($i,$d,$r,$amt,$recv,$handoverCompleted){$this->recordPayment($i,(int)$d['payment_method_id'],$d['reference_number']??null,$d['notes']??null,$amt,[],true,$r->file('receipt'),$recv,$r->boolean('credit_change_to_wallet'));$update=['payment_status'=>'paid','invoice_status'=>'issued','paid_at'=>now(),'paid_by'=>auth()->id(),'require_handoff_verification'=>$r->boolean('require_handoff_verification')];if($handoverCompleted)$update+=['verified_package_ids'=>$i->items->pluck('package_id')->filter()->values()->all(),'verified_by'=>auth()->id(),'verified_at'=>now()];$i->update($update);});app(FinanceEntryService::class)->recordCustomerInvoiceIncome($i->fresh('customer.user'));app(LoyaltyService::class)->awardInvoicePaid($i->fresh('customer'));if($r->boolean('credit_change_to_wallet')&&$i->customer&&max($recv-$amt,0)>0)app(LoyaltyService::class)->creditCash($i->customer,max($recv-$amt,0),'invoice_payment',$i->id,'Change credited from invoice '.$i->invoice_number,'invoice_change');if($handoverCompleted){$this->markInvoicePackagesDelivered(collect([$i->id]));ActivityLog::record('verified','invoices','Verified package handoff and recorded payment for '.$i->invoice_number,['invoice_id'=>$i->id,'tracking_numbers'=>$scanned->all(),'scan_required'=>$r->boolean('require_handoff_verification')]);}return back()->with('success','Invoice marked as paid successfully.');}
 public function verify(Request $r,$id){$i=$this->tenantInvoices()->with('items.package')->findOrFail($id);$this->ensureInvoiceIsNotLocked($i);$s=$this->assertTrackingNumbersMatch($i,$r->validate(['tracking_numbers'=>'required|string'])['tracking_numbers']);$i->update(['verified_package_ids'=>$i->items->pluck('package_id')->filter()->values()->all(),'verified_by'=>auth()->id(),'verified_at'=>now()]);$this->markInvoicePackagesDelivered(collect([$i->id]));ActivityLog::record('verified','invoices','Verified package handoff and scanned packages out for '.$i->invoice_number,['invoice_id'=>$i->id,'tracking_numbers'=>$s->all()]);return back()->with('success','Packages verified, handed over, and closed.');}
 public function voidInvoice($id){$i=$this->tenantInvoices()->findOrFail($id);$i->update(['invoice_status'=>'cancelled','payment_status'=>'cancelled','voided_by'=>auth()->id(),'voided_at'=>now()]);return back()->with('success','Invoice voided successfully.');}
 public function massPayments(Request $r){$customers=$this->tenantCustomers()->with('user')->orderBy('mailbox')->get();$invoices=$this->tenantInvoices()->with(['customer.user','items'])->whereIn('payment_status',['unpaid','partial'])->when($r->filled('customer_id'),fn($q)=>$q->where('customer_id',$r->customer_id))->when($r->filled('start_date'),fn($q)=>$q->whereDate('created_at','>=',$r->start_date))->when($r->filled('end_date'),fn($q)=>$q->whereDate('created_at','<=',$r->end_date))->when($r->filled('invoice_number'),fn($q)=>$q->where('invoice_number','like','%'.$r->invoice_number.'%'))->latest()->paginate($this->perPage($r,15))->withQueryString();return view('courier.invoices.mass',compact('customers','invoices'));}
 public function updateMassPayments(Request $r){$d=$r->validate(['invoice_ids'=>'required|array|min:1','invoice_ids.*'=>'integer','payment_status'=>'required|in:paid,unpaid']);$invoices=$this->tenantInvoices()->whereIn('id',$d['invoice_ids'])->get();foreach($invoices as $i){$i->update(['payment_status'=>$d['payment_status'],'paid_at'=>$d['payment_status']==='paid'?now():null,'paid_by'=>$d['payment_status']==='paid'?auth()->id():null]);if($d['payment_status']==='paid'){$this->recordPayment($i,null,$i->invoice_number,'Recorded from mass payments.',(float)$i->total_jmd);app(FinanceEntryService::class)->recordCustomerInvoiceIncome($i->fresh('customer.user'));app(LoyaltyService::class)->awardInvoicePaid($i->fresh('customer'));$this->markInvoicePackagesDelivered(collect([$i->id]));}}return back()->with('success','Updated '.$invoices->count().' invoice(s).');}
 private function validateInvoiceRequest(Request $r,bool $creating,?int $id=null):void{$this->normalizeInvoiceDiscountInputs($r);$tid=auth()->user()->tenant_id;$existing=$id?$this->tenantInvoices()->find($id):null;if(!$r->filled('payment_status'))$r->merge(['payment_status'=>optional($existing)->payment_status?:'unpaid']);if(!$r->filled('invoice_status'))$r->merge(['invoice_status'=>optional($existing)->invoice_status?:'draft']);$unique=$creating?'unique:invoices,invoice_number,NULL,id,tenant_id,'.$tid:'unique:invoices,invoice_number,'.$id.',id,tenant_id,'.$tid;$r->validate(['customer_id'=>($creating?'nullable':'required').'|exists:customers,id','invoice_number'=>($creating?'nullable':'required').'|string|max:100|'.$unique,'subtotal_jmd'=>'nullable|numeric|min:0','service_fee_jmd'=>'nullable|numeric|min:0','customs_fee_jmd'=>'nullable|numeric|min:0','storage_fee_jmd'=>'nullable|numeric|min:0','gct_amount_jmd'=>'nullable|numeric|min:0','discount_amount_jmd'=>'nullable|numeric|min:0','discount_amount'=>'nullable|numeric|min:0','discount'=>'nullable|numeric|min:0','discount_type'=>'nullable|in:fixed,percent','discount_value'=>'nullable|numeric|min:0','discount_source'=>'nullable|in:value,amount','payment_status'=>'required|in:unpaid,partial,paid,cancelled','invoice_status'=>'required|in:draft,issued,cancelled','due_date'=>'nullable|date','notes'=>'nullable|string','package_ids'=>'nullable|array','package_ids.*'=>'integer','original_package_ids'=>'nullable|array','original_package_ids.*'=>'integer','selected_package_ids'=>'nullable|array','selected_package_ids.*'=>'integer','pricing_tier_id'=>'nullable|integer','require_handoff_verification'=>'nullable|boolean','package_charges'=>'nullable|array','package_charges.*.price_jmd'=>'nullable|numeric|min:0','package_charges.*.service_fee_jmd'=>'nullable|numeric|min:0','package_charges.*.customs_fee_jmd'=>'nullable|numeric|min:0','package_charges.*.storage_fee_jmd'=>'nullable|numeric|min:0','package_charges.*.processing_fee_jmd'=>'nullable|numeric|min:0','package_charges.*.unknown_fee_jmd'=>'nullable|numeric|min:0']);}
 private function createInvoiceForCustomerFromRequest(Customer $c,$packages,Request $r,?string $num=null):Invoice{$this->refreshPackageFees($packages);$tot=$this->forceInvoiceDiscountFromRequest($r,$this->invoiceTotals($r,$packages));$i=Invoice::create($this->invoicePayload($c,$tot,$r)+['tenant_id'=>auth()->user()->tenant_id,'invoice_number'=>$num?:$this->nextCustomerInvoiceNumber(),'added_by'=>auth()->id(),'issued_by'=>($r->invoice_status??null)==='issued'?auth()->id():null]);$this->persistInvoiceDiscount($i,$tot,$r);$this->syncInvoiceItems($i,$packages);$this->markPackagesReadyForHandoff($packages);return $i;}
 private function invoicePayload(Customer $c,array $t,Request $r):array{return ['customer_id'=>$c->id,'outlet_id'=>$c->outlet_id,'mailbox'=>$c->mailbox,'subtotal_jmd'=>$t['subtotal_jmd'],'service_fee_jmd'=>$t['service_fee_jmd'],'customs_fee_jmd'=>$t['customs_fee_jmd'],'storage_fee_jmd'=>$t['storage_fee_jmd'],'processing_fee_jmd'=>$t['processing_fee_jmd'],'gct_amount_jmd'=>$t['gct_amount_jmd'],'discount_amount_jmd'=>$t['discount_amount_jmd'],'discount_type'=>$t['discount_type'],'discount_value'=>$t['discount_value'],'billing_weight_mode'=>$this->billingWeightMode((int)$c->tenant_id),'require_handoff_verification'=>$r->boolean('require_handoff_verification',true),'total_jmd'=>$t['total_jmd'],'payment_status'=>$r->payment_status??'unpaid','invoice_status'=>$r->invoice_status??'draft','paid_at'=>($r->payment_status??null)==='paid'?now():null,'paid_by'=>($r->payment_status??null)==='paid'?auth()->id():null,'due_date'=>$r->due_date,'notes'=>$r->notes];}
 private function forceInvoiceDiscountFromRequest(Request $r,array $totals):array{$base=(float)$totals['subtotal_jmd']+(float)$totals['service_fee_jmd']+(float)$totals['customs_fee_jmd']+(float)$totals['storage_fee_jmd']+(float)$totals['gct_amount_jmd'];$type=$r->input('discount_type','fixed');$type=in_array($type,['fixed','percent'],true)?$type:'fixed';$source=$r->input('discount_source','value');$source=in_array($source,['value','amount'],true)?$source:'value';$valueRaw=$this->postedDiscountValue($r);$amountRaw=$this->postedDiscountAmount($r);$value=$valueRaw!==null&&$valueRaw!==''?(float)$valueRaw:null;$amount=$amountRaw!==null&&$amountRaw!==''?(float)$amountRaw:null;if($source==='amount'&&$amount!==null){$discountAmount=min(max($amount,0),$base);$discountValue=$type==='percent'?($base>0?$discountAmount*100/$base:0):$discountAmount;}elseif($type==='percent'){$discountValue=max(0,(float)($value??0));$discountAmount=min($base*$discountValue/100,$base);}else{$discountValue=max(0,(float)($value??$amount??0));$discountAmount=min($discountValue,$base);}return array_merge($totals,['discount_type'=>$type,'discount_value'=>round(max(0,$discountValue),2),'discount_amount_jmd'=>round(max(0,$discountAmount),2),'total_jmd'=>round(max($base-$discountAmount,0),2)]);}
 private function postedDiscountValue(Request $r){foreach(['discount_value','discount','discount_amount','discount_amount_jmd'] as $key){if($r->filled($key))return $r->input($key);}return null;}
 private function postedDiscountAmount(Request $r){foreach(['discount_amount_jmd','discount_amount','discount'] as $key){if($r->filled($key))return $r->input($key);}return null;}
 private function normalizeInvoiceDiscountInputs(Request $r):void{$amount=$this->postedDiscountAmount($r);$value=$this->postedDiscountValue($r);$merge=[];if(!$r->filled('discount_amount_jmd')&&$amount!==null&&$amount!=='')$merge['discount_amount_jmd']=$amount;if(!$r->filled('discount_value')&&$value!==null&&$value!=='')$merge['discount_value']=$value;if(!$r->filled('discount_source'))$merge['discount_source']=$r->filled('discount_amount_jmd')&&!$r->filled('discount_value')?'amount':'value';if($merge)$r->merge($merge);}
 private function persistInvoiceDiscount(Invoice $invoice,array $totals,?Request $request=null):void{DB::table('invoices')->where('id',$invoice->id)->update(['discount_amount_jmd'=>$totals['discount_amount_jmd'],'discount_type'=>$totals['discount_type'],'discount_value'=>$totals['discount_value'],'total_jmd'=>$totals['total_jmd'],'updated_at'=>now()]);$fresh=DB::table('invoices')->where('id',$invoice->id)->first(['discount_amount_jmd','discount_value','total_jmd']);if(!$fresh||round((float)$fresh->discount_amount_jmd,2)!==round((float)$totals['discount_amount_jmd'],2)||round((float)$fresh->discount_value,2)!==round((float)$totals['discount_value'],2)||round((float)$fresh->total_jmd,2)!==round((float)$totals['total_jmd'],2))throw ValidationException::withMessages(['discount_value'=>'Invoice discount could not be saved. Please retry and contact support if it continues.']);$invoice->forceFill(['discount_amount_jmd'=>$totals['discount_amount_jmd'],'discount_type'=>$totals['discount_type'],'discount_value'=>$totals['discount_value'],'total_jmd'=>$totals['total_jmd']])->syncOriginal();$posted=$request?['posted_discount_value'=>$request->input('discount_value'),'posted_discount_amount_jmd'=>$request->input('discount_amount_jmd'),'posted_discount'=>$request->input('discount'),'posted_discount_amount'=>$request->input('discount_amount'),'posted_discount_source'=>$request->input('discount_source')]:[];$context=['invoice_id'=>$invoice->id,'discount_amount_jmd'=>$totals['discount_amount_jmd'],'discount_type'=>$totals['discount_type'],'discount_value'=>$totals['discount_value'],'total_jmd'=>$totals['total_jmd']]+$posted;Log::info('Invoice discount persisted',$context);ActivityLog::record('updated','invoices','Persisted invoice discount for '.$invoice->invoice_number.' - posted value '.($posted['posted_discount_value']??'null').', posted amount '.($posted['posted_discount_amount_jmd']??'null').', discount JMD '.number_format((float)$totals['discount_amount_jmd'],2).', value '.number_format((float)$totals['discount_value'],2).', total JMD '.number_format((float)$totals['total_jmd'],2),$context);}
 private function preventAccidentalInvoiceZeroOut(Invoice $invoice,$packages,array $totals,Request $r):void{$hadValue=(float)$invoice->total_jmd>0||$invoice->items->isNotEmpty();$noPackages=$packages->isEmpty();$base=(float)$totals['subtotal_jmd']+(float)$totals['service_fee_jmd']+(float)$totals['customs_fee_jmd']+(float)$totals['storage_fee_jmd']+(float)$totals['gct_amount_jmd'];$hasAnyRequestedAmount=collect(['subtotal_jmd','service_fee_jmd','customs_fee_jmd','storage_fee_jmd','gct_amount_jmd'])->contains(fn($key)=>(float)$r->input($key,0)>0)||collect($r->input('package_charges',[]))->flatMap(fn($charges)=>(array)$charges)->contains(fn($value)=>(float)$value>0);if($hadValue&&$noPackages&&$base<=0&&!$hasAnyRequestedAmount)throw ValidationException::withMessages(['package_ids'=>'This invoice currently has value but no package rows were submitted. Refresh the invoice and try again to avoid saving it as zero.']);}
 private function applyExistingInvoiceItemCharges($packages,Invoice $invoice,array $charges=[]):void{if($packages->isEmpty())return;$items=$invoice->items()->whereNotNull('package_id')->get()->keyBy('package_id');foreach($packages as $p){if(array_key_exists($p->id,$charges))continue;$item=$items->get($p->id);if(!$item)continue;$p->price_jmd=(float)$item->package_price_jmd;$p->storage_fee=(float)$item->storage_fee_jmd;$p->processing_fee_jmd=(float)$item->processing_fee_jmd;$p->invoice_unknown_fee_jmd=(float)$item->unknown_fee_jmd;$p->invoice_service_fee_jmd=(float)$item->service_fee_jmd;$p->invoice_customs_fee_jmd=(float)$item->customs_fee_jmd;$p->invoice_rate_jmd=(float)$item->rate_jmd;$p->invoice_billable_weight=(float)$item->billable_weight;}}
 private function invoiceTotals(Request $r,$packages):array{$pkg=0;$storage=0;$processing=0;$svc=0;$custom=0;$charges=$r->input('package_charges',[]);foreach($packages as $p){$o=$charges[$p->id]??[];$p->price_jmd=(float)($o['price_jmd']??$p->price_jmd);$p->storage_fee=(float)($o['storage_fee_jmd']??$p->storage_fee);$p->processing_fee_jmd=(float)($o['processing_fee_jmd']??$p->processing_fee_jmd);$p->invoice_unknown_fee_jmd=(float)($o['unknown_fee_jmd']??($p->invoice_unknown_fee_jmd??$p->unknown_fee_jmd??0));$p->invoice_service_fee_jmd=(float)($o['service_fee_jmd']??($p->invoice_service_fee_jmd??0));$p->invoice_customs_fee_jmd=(float)($o['customs_fee_jmd']??($p->invoice_customs_fee_jmd??0));$pkg+=(float)$p->price_jmd+(float)$p->processing_fee_jmd+(float)$p->invoice_unknown_fee_jmd;$storage+=(float)$p->storage_fee;$processing+=(float)$p->processing_fee_jmd;$svc+=(float)$p->invoice_service_fee_jmd;$custom+=(float)$p->invoice_customs_fee_jmd;}$subtotal=$packages->isNotEmpty()?$pkg:(float)$r->input('subtotal_jmd',0);$storage=$packages->isNotEmpty()?$storage:(float)$r->input('storage_fee_jmd',0);$svc+=(float)$r->input('service_fee_jmd',0);$custom+=(float)$r->input('customs_fee_jmd',0);$gct=(float)$r->input('gct_amount_jmd',0);$base=$subtotal+$storage+$svc+$custom+$gct;$type=$r->input('discount_type','fixed');$type=in_array($type,['fixed','percent'],true)?$type:'fixed';$source=$r->input('discount_source','value');$source=in_array($source,['value','amount'],true)?$source:'value';$valueInput=$r->input('discount_value');$amountInput=$r->input('discount_amount_jmd');$hasValue=$valueInput!==null&&$valueInput!=='';$hasAmount=$amountInput!==null&&$amountInput!=='';$value=(float)($hasValue?$valueInput:0);$amount=(float)($hasAmount?$amountInput:0);if($source==='amount'&&$hasAmount){$disc=min(max($amount,0),$base);$val=$type==='percent'?($base>0?$disc*100/$base:0):$disc;}elseif($type==='percent'){$val=$hasValue?$value:($base>0?$amount*100/$base:0);$disc=min($base*$val/100,$base);}else{$val=$hasValue?$value:$amount;$disc=min($val,$base);}return ['subtotal_jmd'=>round($subtotal,2),'service_fee_jmd'=>round($svc,2),'customs_fee_jmd'=>round($custom,2),'storage_fee_jmd'=>round($storage,2),'processing_fee_jmd'=>round($processing,2),'gct_amount_jmd'=>round($gct,2),'discount_amount_jmd'=>round($disc,2),'discount_type'=>$type,'discount_value'=>round($val,2),'total_jmd'=>round(max($base-$disc,0),2)];}
 private function afterInvoicesCreated($invoices,CustomerNotificationService $n,string $msg){foreach($invoices as $i){ActivityLog::record('created','invoices','Created invoice '.$i->invoice_number,['invoice_id'=>$i->id,'total_jmd'=>$i->total_jmd]);if($n->invoiceCreated($i->fresh(['tenant','customer.user','items.package'])))$i->update(['email_sent'=>true]);if($i->payment_status==='paid'){$this->recordPayment($i);app(FinanceEntryService::class)->recordCustomerInvoiceIncome($i->fresh('customer.user'));app(LoyaltyService::class)->awardInvoicePaid($i->fresh('customer'));}}return redirect()->route('courier.invoices.index')->with('success',$msg);}
 private function bulkInvoiceData(Request $r):array{return $r->validate(['due_date'=>'nullable|date','notes'=>'nullable|string|max:1000','customer_ids'=>'nullable|array','customer_ids.*'=>'integer','send_email'=>'nullable|boolean','selected_only'=>'nullable|boolean']);}
 private function bulkInvoicePreviewGroups(?Manifest $m=null){return $this->bulkInvoiceablePackages($m)->groupBy('customer_id')->map(function($pkgs){$c=$pkgs->first()->customer;return ['customer'=>$c,'packages'=>$pkgs,'package_count'=>$pkgs->count(),'estimated_total'=>$pkgs->sum(fn(Package $p)=>(float)$p->price_jmd+(float)$p->storage_fee+(float)$p->processing_fee_jmd+(float)$p->unknown_fee_jmd)];})->filter(fn($g)=>$g['customer'])->sortBy(fn($g)=>optional($g['customer'])->mailbox)->values();}
 private function bulkInvoiceablePackages(?Manifest $m=null){$q=$this->invoiceablePackages()->whereNotNull('customer_id')->with(['customer.user','customer.pricingTier','outlet'])->orderBy('customer_id')->orderBy('mailbox')->orderBy('date_received');if($m)$q->where('manifest_id',$m->id);$packages=$q->get();$this->refreshPackageFees($packages);return $packages;}
 private function createBulkInvoices($packages,array $d,CustomerNotificationService $n):array{$ids=collect($d['customer_ids']??[])->map(fn($id)=>(int)$id)->filter()->values();$packages=$packages->filter(fn(Package $p)=>$p->customer_id);if(!empty($d['selected_only'])&&$ids->isEmpty())$packages=collect();elseif($ids->isNotEmpty())$packages=$packages->filter(fn(Package $p)=>$ids->contains((int)$p->customer_id));if($packages->isEmpty())return ['created'=>0,'sent'=>0,'skipped'=>0,'invoice_ids'=>[]];$created=DB::transaction(fn()=> $packages->groupBy('customer_id')->map(fn($pkgs)=>$this->createBulkInvoiceForCustomer($pkgs->first()->customer,$pkgs->values(),$d))->filter()->values());$sent=0;if(!empty($d['send_email']))foreach($created as $i)if($n->invoiceCreated($i->fresh(['tenant','customer.user','items.package']))){$i->update(['email_sent'=>true]);$sent++;}ActivityLog::record('bulk_created','invoices','Bulk created '.$created->count().' customer invoice(s)',['invoice_ids'=>$created->pluck('id')->all(),'emails_sent'=>$sent]);return ['created'=>$created->count(),'sent'=>$sent,'skipped'=>0,'invoice_ids'=>$created->pluck('id')->all()];}
 private function createBulkInvoiceForCustomer(Customer $c,$pkgs,array $d):Invoice{return $this->createInvoiceForCustomerFromRequest($c,$pkgs,new Request(['payment_status'=>'unpaid','invoice_status'=>'issued','due_date'=>$d['due_date']??null,'notes'=>$d['notes']??null,'discount_type'=>'fixed','discount_value'=>0,'require_handoff_verification'=>true]));}
 private function bulkInvoiceRedirect(array $res,string $route,array $params=[]){if($res['created']===0)return redirect()->route($route,$params)->withErrors(['bulk_invoices'=>'No uninvoiced customer packages were found for bulk invoice generation.']);return redirect()->route($route,$params)->with('success','Created '.$res['created'].' invoice(s). Sent '.$res['sent'].' customer notification(s).');}
 private function syncInvoiceItems(Invoice $i,$packages):void
 {
  $i->items()->delete();
  foreach($packages as $p){
   $svc=(float)($p->invoice_service_fee_jmd??0);
   $cust=(float)($p->invoice_customs_fee_jmd??0);
   $unk=(float)($p->invoice_unknown_fee_jmd??$p->unknown_fee_jmd??0);
   $isSea=$this->shippingModeCategory((int)$p->tenant_id,(string)$p->freight_type)==='sea';
   $measure=$isSea?(float)($p->volume_cuft?:$p->weight):(float)$p->weight;
   $billable=(float)($p->invoice_billable_weight??$this->billableWeight($measure,$this->billingWeightMode((int)$p->tenant_id)));
   $rate=(float)($p->invoice_rate_jmd??$p->price_jmd);
   $total=(float)$p->price_jmd+(float)$p->storage_fee+(float)$p->processing_fee_jmd+$unk+$svc+$cust;
   InvoiceItem::create(['tenant_id'=>$i->tenant_id,'invoice_id'=>$i->id,'package_id'=>$p->id,'tracking_number'=>$p->tracking_number,'description'=>$p->description?:$p->merchant,'freight_type'=>$p->freight_type,'weight'=>$measure,'billable_weight'=>$billable,'measure_unit'=>$isSea?'cu.ft':'lb','rate_region'=>$p->region??null,'package_price_usd'=>$p->price_usd,'package_price_jmd'=>$p->price_jmd,'rate_jmd'=>$rate,'service_fee_jmd'=>$svc,'customs_fee_jmd'=>$cust,'storage_fee_jmd'=>$p->storage_fee,'processing_fee_jmd'=>$p->processing_fee_jmd,'unknown_fee_jmd'=>$unk,'unknown_fee_reason'=>$p->unknown_fee_reason,'total_jmd'=>$total]);
  }
 }
 private function invoiceablePackages(array $include=[]){return $this->tenantPackages()->whereNotNull('manifest_id')->where(function($q)use($include){$q->whereDoesntHave('invoiceItems.invoice',fn($invoice)=>$invoice->whereNull('voided_at')->where('invoice_status','!=','cancelled')->where('payment_status','!=','cancelled'));if($include)$q->orWhereIn('id',$include);});}
 private function selectedInvoicePackagesForCustomers(array $ids){$ids=collect($ids)->map(fn($id)=>(int)$id)->filter()->unique()->values()->all();return $ids?$this->invoiceablePackages($ids)->whereIn('id',$ids)->with(['customer.user','customer.pricingTier','outlet'])->get()->filter(fn($p)=>$p->customer_id):collect();}
 private function selectedInvoicePackages(array $ids,int $customerId,array $include=[]){$ids=collect($ids)->map(fn($id)=>(int)$id)->filter()->unique()->values()->all();return $ids?$this->invoiceablePackages(array_merge($include,$ids))->whereIn('id',$ids)->where('customer_id',$customerId)->with(['customer.user','outlet'])->get():collect();}
 private function directInvoiceablePackage(){return $this->tenantPackages()->whereDoesntHave('invoiceItems.invoice',fn($invoice)=>$invoice->whereNull('voided_at')->where('invoice_status','!=','cancelled')->where('payment_status','!=','cancelled'));}
 private function refreshPackageFees($packages,?Invoice $invoice=null):void{foreach($packages as $p){$mode=$this->billingWeightMode((int)$p->tenant_id);$billable=$this->billablePackageMeasure($p,$mode);$storageDays=$this->storageDaysForPackage($invoice);$storageFee=$this->storageFee((int)$p->tenant_id,$storageDays);$p->storage_days=$storageDays;$p->storage_fee=$storageFee;if($p->exists&&((int)$p->getOriginal('storage_days')!==$storageDays||round((float)$p->getOriginal('storage_fee'),2)!==round($storageFee,2)))Package::whereKey($p->id)->update(['storage_days'=>$storageDays,'storage_fee'=>$storageFee,'updated_at'=>now()]);$p->invoice_billable_weight=$billable;$rate=$this->packageRate($p);if($rate){$price=$rate->priceFor($billable,$p->delivery_type?:'pickup');$p->price_jmd=$price;$p->invoice_rate_jmd=$price;$p->processing_fee_jmd=(float)$rate->processing_fee_jmd>0?(float)$rate->processing_fee_jmd:$this->processingFee((int)$p->tenant_id);$p->setAttribute('invoice_rate_matched',true);}else{$p->invoice_rate_jmd=$p->price_jmd;$p->processing_fee_jmd=$this->processingFee((int)$p->tenant_id);$p->setAttribute('invoice_rate_matched',false);}}}
 private function packageRate(Package $p):?WeightRate{$weight=$this->billablePackageMeasure($p,$this->billingWeightMode($p->tenant_id));$customer=$p->customer;$outletId=optional($customer)->outlet_id?:$p->outlet_id;$category=$this->shippingModeCategory((int)$p->tenant_id,(string)$p->freight_type);$region=strtolower($p->normalizedRegion());$base=fn()=>WeightRate::where('tenant_id',$p->tenant_id)->where('freight_type',$p->freight_type)->where('is_active',true)->where(function($q)use($outletId){$q->whereNull('outlet_id');if($outletId)$q->orWhere('outlet_id',$outletId);})->where(function($q)use($customer){$q->whereNull('pricing_tier_id');if($customer&&$customer->pricing_tier_id)$q->orWhere('pricing_tier_id',$customer->pricing_tier_id);})->where(function($q)use($region){$q->whereNull('region')->orWhere('region','')->orWhereRaw('LOWER(region) = ?',[$region]);})->orderByRaw("CASE WHEN LOWER(COALESCE(region, '')) = ? THEN 0 WHEN region IS NULL OR region = '' THEN 1 ELSE 2 END",[$region])->orderByRaw('outlet_id is null')->orderByRaw('pricing_tier_id is null');$rate=$base()->where($this->invoiceRateRangeClause($category,$weight))->orderBy('min_weight')->first();return $rate?:$base()->where($this->invoiceFinalRateClause($category,$weight))->orderByDesc('min_weight')->first();}
 private function billablePackageMeasure(Package $p,string $mode):float{$measure=(float)$p->weight;if($this->shippingModeCategory((int)$p->tenant_id,(string)$p->freight_type)==='sea')$measure=(float)($p->volume_cuft?:$p->weight);return $this->billableWeight($measure,$mode);}
 private function invoiceRateRangeClause(string $category,float $measure):\Closure{return function($q)use($category,$measure){if($category!=='sea'){$q->where('min_weight','<=',$measure)->where(fn($r)=>$r->whereNull('max_weight')->orWhere('max_weight','>=',$measure));return;}$cbm=$measure/WeightRate::CBM_TO_CUFT;$q->where(function($u)use($measure,$cbm){$u->where(function($c)use($measure){$c->where(fn($unit)=>$unit->whereNull('volume_unit')->orWhere('volume_unit','cuft'))->where('min_weight','<=',$measure)->where(fn($r)=>$r->whereNull('max_weight')->orWhere('max_weight','>=',$measure));})->orWhere(function($c)use($cbm){$c->where('volume_unit','cbm')->where('min_weight','<=',$cbm)->where(fn($r)=>$r->whereNull('max_weight')->orWhere('max_weight','>=',$cbm));});});};}
 private function invoiceFinalRateClause(string $category,float $measure):\Closure{return function($q)use($category,$measure){if($category!=='sea'){$q->where('min_weight','<=',$measure);return;}$cbm=$measure/WeightRate::CBM_TO_CUFT;$q->where(function($u)use($measure,$cbm){$u->where(function($c)use($measure){$c->where(fn($unit)=>$unit->whereNull('volume_unit')->orWhere('volume_unit','cuft'))->where('min_weight','<=',$measure);})->orWhere(function($c)use($cbm){$c->where('volume_unit','cbm')->where('min_weight','<=',$cbm);});});};}
 private function shippingModeCategory(int $tenantId,string $freightType):string{return ShippingMode::where('tenant_id',$tenantId)->where('code',$freightType)->value('category')?:($freightType==='sea'?'sea':($freightType==='local'?'local':'air'));}
 private function billingWeightMode(int $tenantId):string{$mode=\App\Models\TenantSetting::getValue($tenantId,'billing_weight_mode','actual');return in_array($mode,['actual','round_up','round_down'],true)?$mode:'actual';}
 private function billableWeight(float $weight,string $mode):float{if($weight<=0)return 0;return match($mode){'round_up'=>ceil($weight),'round_down'=>max(floor($weight),1),default=>$weight};}
 private function storageDaysForPackage(?Invoice $invoice=null):int
 {
  return $invoice&&$invoice->created_at?max(0,(int)$invoice->created_at->copy()->startOfDay()->diffInDays(now()->startOfDay())):0;
 }
 private function storageFee(int $tenantId,int $storageDays):float{$days=max(0,$storageDays);$freeDays=(int)\App\Models\TenantSetting::getValue($tenantId,'storage_free_days',0);if($days<=$freeDays)return 0.0;$flat=(float)\App\Models\TenantSetting::getValue($tenantId,'storage_flat_fee_jmd',0);$daily=(float)\App\Models\TenantSetting::getValue($tenantId,'storage_daily_increment_jmd',0);return round($flat+max($days-$freeDays,0)*$daily,2);}
 private function processingFee(int $tenantId):float{return (float)\App\Models\TenantSetting::getValue($tenantId,'processing_fee_jmd',0);}
 private function tenantInvoices(){$q=Invoice::where('tenant_id',auth()->user()->tenant_id);if(auth()->user()->user_type==='staff'&&auth()->user()->outlet_id)$q->where('outlet_id',auth()->user()->outlet_id);return $q;}
 private function filteredTenantInvoices(Request $r){return $this->tenantInvoices()->when($r->filled('q'),function($q)use($r){$term=trim((string)$r->q);$t='%'.$term.'%';$tokens=collect(preg_split('/\s+/',$term))->filter()->values();$q->where(fn($n)=>$n->where('invoice_number','like',$t)->orWhere('mailbox','like',$t)->orWhereHas('customer.user',function($u)use($t,$tokens){$u->where('first_name','like',$t)->orWhere('last_name','like',$t)->orWhere('full_name','like',$t)->orWhere('email','like',$t)->orWhereRaw("CONCAT_WS(' ', first_name, last_name) LIKE ?",[$t])->orWhereRaw("CONCAT_WS(' ', last_name, first_name) LIKE ?",[$t]);if($tokens->count()>1)$u->orWhere(function($names)use($tokens){foreach($tokens as $token)$names->where('full_name','like','%'.$token.'%');});}));})->when($r->filled('payment_status'),fn($q)=>$q->where('payment_status',$r->payment_status))->when($r->filled('invoice_status'),fn($q)=>$q->where('invoice_status',$r->invoice_status))->when($r->filled('date_from'),fn($q)=>$q->whereDate('created_at','>=',$r->date_from))->when($r->filled('date_to'),fn($q)=>$q->whereDate('created_at','<=',$r->date_to));}
 private function tenantPackages(){$q=Package::where('tenant_id',auth()->user()->tenant_id);if(auth()->user()->user_type==='staff'&&auth()->user()->outlet_id)$q->where('outlet_id',auth()->user()->outlet_id);return $q;}
 private function tenantCustomers(){$q=Customer::where('tenant_id',auth()->user()->tenant_id);if(auth()->user()->user_type==='staff'&&auth()->user()->outlet_id)$q->where('outlet_id',auth()->user()->outlet_id);return $q;}
 private function pricingTiers(){return PricingTier::where('tenant_id',auth()->user()->tenant_id)->where('is_active',true)->orderByDesc('is_default')->orderBy('name')->get();}
 private function outlets(){return Outlet::where('tenant_id',auth()->user()->tenant_id)->orderBy('name')->get();}
 private function shippingModes(){return ShippingMode::where('tenant_id',auth()->user()->tenant_id)->where('is_active',true)->orderBy('sort_order')->orderBy('name')->get();}
 private function paymentMethods(){return PaymentMethod::where('is_active',true)->where(fn($q)=>$q->whereNull('tenant_id')->orWhere('tenant_id',auth()->user()->tenant_id))->orderBy('name')->get();}
 private function validPaymentMethod(int $id):?PaymentMethod{return $this->paymentMethods()->firstWhere('id',$id);}
 private function recordPayment(Invoice $i,?int $method=null,?string $ref=null,?string $notes=null,?float $amount=null,array $points=[],bool $replace=true,?UploadedFile $receipt=null,?float $received=null,bool $changeToWallet=false):Payment{$paymentAmount=(float)($amount??$i->total_jmd);$receivedAmount=(float)($received??$paymentAmount);$vals=['customer_id'=>$i->customer_id,'outlet_id'=>$i->outlet_id,'payment_number'=>$this->nextPaymentNumber($i->tenant_id,$i->id),'amount'=>$paymentAmount,'amount_received'=>$receivedAmount,'change_due'=>max($receivedAmount-$paymentAmount,0),'change_to_wallet'=>$changeToWallet,'payment_method_id'=>$method,'reference_number'=>$ref?:$i->invoice_number,'notes'=>$notes?:'Recorded from invoice payment status.','received_by'=>auth()->id(),'approved_by'=>auth()->id(),'approved_at'=>now(),'paid_at'=>$i->paid_at??now()];if($receipt)$vals+=['receipt_path'=>$receipt->store('payment-receipts','public'),'receipt_original_name'=>$receipt->getClientOriginalName(),'receipt_mime_type'=>$receipt->getClientMimeType()];$p=$replace?Payment::where(['tenant_id'=>$i->tenant_id,'invoice_id'=>$i->id,'status'=>'approved'])->first():null;if($p&&$receipt&&$p->receipt_path&&Storage::disk('public')->exists($p->receipt_path))Storage::disk('public')->delete($p->receipt_path);if($p){$p->update($vals);return $p->fresh();}return Payment::create($vals+['tenant_id'=>$i->tenant_id,'invoice_id'=>$i->id,'status'=>'approved']);}
 private function nextPaymentNumber(int $tenantId,int $invoiceId):string{$base='PAY-'.now()->format('Ymd').'-'.str_pad((string)$invoiceId,6,'0',STR_PAD_LEFT);$num=$base;$seq=1;while(Payment::where('tenant_id',$tenantId)->where('payment_number',$num)->exists())$num=$base.'-'.(++$seq);return $num;}
 private function nextCustomerInvoiceNumber():string{$tid=auth()->user()->tenant_id;$prefix='INV-'.now()->format('Ymd').'-';$seq=Invoice::where('tenant_id',$tid)->where('invoice_number','like',$prefix.'%')->count()+1;do{$num=$prefix.str_pad((string)$seq++,4,'0',STR_PAD_LEFT);}while(Invoice::where('tenant_id',$tid)->where('invoice_number',$num)->exists());return $num;}
 private function invoiceRemainingBalance(Invoice $i):float{$i->loadMissing('payments');return max(0,round((float)$i->total_jmd-(float)$i->payments->where('status','approved')->sum('amount'),2));}
 private function markPackagesReadyForHandoff($packages):void{foreach($packages as $p){$sid=$this->readyStatusIdForPackage($p);if(!$sid||(int)$p->status_id===(int)$sid)continue;Package::whereKey($p->id)->update(['status_id'=>$sid]);$p->forceFill(['status_id'=>$sid])->syncOriginalAttribute('status_id');PackageLog::create(['tenant_id'=>$p->tenant_id,'package_id'=>$p->id,'status_id'=>$sid,'note'=>'Marked ready automatically after invoice generation','location'=>optional(auth()->user()->outlet)->name,'added_by'=>auth()->id(),'created_at'=>now()]);}}
 private function readyStatusIdForPackage(Package $p):?int{$pref=str_contains(strtolower((string)$p->delivery_type),'delivery')?'Ready for Delivery':'Ready for Pickup';return PackageStatus::where('tenant_id',$p->tenant_id)->where(fn($q)=>$q->where('name','like','%'.$pref.'%')->orWhere('slug','like','%'.strtolower(str_replace(' ','-',$pref)).'%'))->value('id')?:PackageStatus::where('tenant_id',$p->tenant_id)->where(fn($q)=>$q->where('name','like','%Ready%')->orWhere('slug','like','%ready%'))->value('id');}
 private function markInvoicePackagesDelivered($invoiceIds):void{$ids=InvoiceItem::whereIn('invoice_id',$invoiceIds)->whereNotNull('package_id')->pluck('package_id');$packages=Package::where('tenant_id',auth()->user()->tenant_id)->whereIn('id',$ids)->with('customer')->get();$loyalty=app(LoyaltyService::class);foreach($packages as $p){$sid=$this->handoverStatusIdForPackage($p);if($p->date_delivered&&(!$sid||(int)$p->status_id===(int)$sid))continue;$update=['date_delivered'=>now()];if($sid)$update['status_id']=$sid;$p->update($update);$p->forceFill($update)->syncOriginal();PackageLog::create(['tenant_id'=>$p->tenant_id,'package_id'=>$p->id,'status_id'=>$sid?:$p->status_id,'note'=>'Verified package handoff to client from invoice scan-out','location'=>optional(auth()->user()->outlet)->name,'added_by'=>auth()->id(),'created_at'=>now()]);if($p->customer){$loyalty->refreshCustomerTier($p->customer);$loyalty->awardPackageCollected($p->fresh('customer'));}}}
 private function handoverStatusIdForPackage(Package $p):?int{$statuses=PackageStatus::where('tenant_id',$p->tenant_id)->where('is_active',true)->orderBy('sort_order')->orderBy('name')->get();$isPickup=str_contains(strtolower((string)$p->delivery_type),'pickup');$preferred=$isPickup?['picked up','picked','collected','handed over','handover','delivered']:['delivered','handed over','handover'];$blocked=['ready','available','out for delivery','pending','received'];foreach($preferred as $term){$status=$statuses->first(function($status)use($term,$blocked){$name=strtolower((string)$status->name);$slug=strtolower((string)$status->slug);foreach($blocked as $bad){if(str_contains($name,$bad)||str_contains($slug,$bad))return false;}return str_contains($name,$term)||str_contains($slug,str_replace(' ','-',$term));});if($status)return $status->id;}return PackageStatus::firstOrCreate(['tenant_id'=>$p->tenant_id,'slug'=>'delivered'],['name'=>'Delivered','color'=>'#16a34a','icon'=>'fa-check-circle','is_default'=>false,'sort_order'=>((int)PackageStatus::where('tenant_id',$p->tenant_id)->max('sort_order'))+10,'is_active'=>true])->id;}
 private function isFinalHandoverStatus(Package $p):bool{$name=strtolower((string)optional($p->status)->name);$slug=strtolower((string)optional($p->status)->slug);foreach(['ready','available','out for delivery','pending','received'] as $bad){if(str_contains($name,$bad)||str_contains($slug,$bad))return false;}foreach(['delivered','picked','collected','handed over','handover'] as $term){if(str_contains($name,$term)||str_contains($slug,str_replace(' ','-',$term)))return true;}return false;}
 private function assertTrackingNumbersMatch(Invoice $i,string $nums){$expected=$i->items->filter(fn($it)=>$it->tracking_number||optional($it->package)->supplier_tracking)->map(fn($it)=>['label'=>$it->tracking_number?:optional($it->package)->supplier_tracking,'keys'=>collect([$it->tracking_number,optional($it->package)->supplier_tracking])->map(fn($v)=>strtoupper(trim((string)$v)))->filter()->unique()->values()])->values();$scanned=collect(preg_split('/[\r\n,]+/',$nums))->map(fn($v)=>strtoupper(trim($v)))->filter()->unique()->values();if($expected->isEmpty())throw ValidationException::withMessages(['tracking_numbers'=>'Verification failed. This invoice has no package tracking numbers to verify.']);if($scanned->count()!==$expected->count())throw ValidationException::withMessages(['tracking_numbers'=>'Verification failed. Scan every package manually. Expected '.$expected->count().' tracking number'.($expected->count()===1?'':'s').', received '.$scanned->count().'.']);$all=$expected->flatMap(fn($it)=>$it['keys'])->unique()->values();$missing=$expected->reject(fn($it)=>$it['keys']->intersect($scanned)->isNotEmpty())->pluck('label')->values();$unexpected=$scanned->diff($all)->values();if($missing->isNotEmpty()||$unexpected->isNotEmpty())throw ValidationException::withMessages(['tracking_numbers'=>'Verification failed. Missing: '.$missing->implode(', ').' Unexpected: '.$unexpected->implode(', ')]);return $scanned;}
 private function authorizeManifestForInvoices(Manifest $m):Manifest{abort_if((int)$m->tenant_id!==(int)auth()->user()->tenant_id,404);if(auth()->user()->user_type==='staff'&&auth()->user()->outlet_id)abort_unless(Package::where('tenant_id',auth()->user()->tenant_id)->where('manifest_id',$m->id)->where('outlet_id',auth()->user()->outlet_id)->exists(),404);return $m;}
 private function ensureInvoiceIsNotLocked(Invoice $i):void{if($i->isLocked())throw ValidationException::withMessages(['invoice'=>'This invoice is voided, permanently locked, and archived. It cannot be reopened or modified.']);}
}







